<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {api as requestApi,money} from './api'
import RecordEditor from './RecordEditor.vue'
import MissionCompletion from './MissionCompletion.vue'
import DeliveryReceipt from './DeliveryReceipt.vue'
import ClientDiscussion from './ClientDiscussion.vue'
const props=defineProps<{catalog:any[],org:any}>()
function api(path:string,method='GET',body?:any){return requestApi(path,method,body,true,props.org.id)}
const rows=ref<any[]>([]),count=ref(0),page=ref(1),query=ref(''),archived=ref('false'),sort=ref('name'),error=ref(''),detail=ref<any>(null),tab=ref('overview'),history=ref<any[]>([]),historyCount=ref(0),historyPage=ref(1)
const editor=ref<any>(null),record=ref<any>(null),prefill=ref<any>(null),loading=ref(false)
const completing=ref<any>(null),receipt=ref<any>(null),discussion=ref(false)
let timer:ReturnType<typeof setTimeout>|undefined
let historyVersion=0
const states:any={draft:'Brouillon',sent:'Envoyé',accepted:'Accepté',refused:'Refusé',expired:'Expiré',issued:'Émise',paid:'Payée',partial:'Partiellement payée',confirmed:'Confirmée',planned:'Planifiée',active:'En cours',completed:'Terminée',cancelled:'Annulée'}
const labels:any={overview:'Aperçu',quotes:'Devis',orders:'Commandes',missions:'Missions / Livraisons',invoices:'Factures',payments:'Paiements',documents:'Documents',contacts:'Contacts',activity:'Activité'}
const writable=computed(()=>props.catalog.find(x=>x.key==='partners')?.writable)
async function run(fn:()=>Promise<void>){error.value='';try{await fn()}catch(e:any){error.value=e.message}}
async function load(){loading.value=true;await run(async()=>{const r=await api(`clients?page=${page.value}&q=${encodeURIComponent(query.value)}&archived=${archived.value}&sort=${sort.value}`);rows.value=r.results;count.value=r.count});loading.value=false}
function search(){clearTimeout(timer);timer=setTimeout(()=>{page.value=1;load()},300)}
async function show(id:string){await run(async()=>{detail.value=await api('clients/'+id);tab.value='overview';discussion.value=false;historyPage.value=1;history.value=[]})}
async function loadHistory(){if(!detail.value||tab.value==='overview')return;const version=++historyVersion;await run(async()=>{const id=detail.value.customer.id,key=tab.value;let path=key==='activity'?`clients/${id}/activity?page=${historyPage.value}`:`${key==='quotes'?'invoices':key}?customer=${id}&page=${historyPage.value}${['quotes','invoices'].includes(key)?'&kind='+(key==='quotes'?'quote':'invoice'):''}`;const r=await api(path);if(version!==historyVersion||tab.value!==key||detail.value?.customer.id!==id)return;history.value=r.results;historyCount.value=r.count})}
function selectTab(key:string){tab.value=key;history.value=[];historyCount.value=0;historyPage.value=1;loadHistory()}
function edit(resource:string,row:any=null,defaults:any=null){editor.value=props.catalog.find(x=>x.key===resource);record.value=row;prefill.value=defaults}
function create(resource:string,kind?:string){const today=new Date().toISOString().slice(0,10);edit(resource,null,{customer:detail.value.customer.id,...(resource==='invoices'?{kind:kind||'invoice',date:today,due_date:today,lines:[{description:'Transport',quantity:'1',price:'0',tax_rate:'0'}]}:resource==='orders'?{planned_date:today}:{} )})}
async function saved(){editor.value=null;if(detail.value){const id=detail.value.customer.id;detail.value=await api('clients/'+id);await loadHistory()}await load()}
async function archive(){await run(async()=>{await api(`clients/${detail.value.customer.id}/${detail.value.customer.archived_at?'restore':'archive'}`,'POST',{});await show(detail.value.customer.id);await load()})}
async function commercial(row:any,action:string){await run(async()=>{await api(`commercial/${row.id}/${action}`,'POST',{});await saved()})}
async function act(resource:string,row:any,action:string){await run(async()=>{await api(`${resource}/${row.id}/actions/${action}`,'POST',{});await saved()})}
function plan(row:any){const departure=row.window_start||row.planned_date+'T08:00:00';edit('missions',null,{order:row.id,origin:row.origin,destination:row.destination,departure,arrival:row.window_end||row.planned_date+'T12:00:00',loaded_quantity:row.quantity,notes:row.notes})}
function payment(row:any){edit('payments',null,{invoice:row.id,date:new Date().toISOString().slice(0,10),amount:row.balance||'',reference:''})}
async function invite(){await run(async()=>{await api('portal-access','POST',{mode:'existing',partner:detail.value.customer.id,email:detail.value.customer.email});await show(detail.value.customer.id)})}
async function portalAction(action:string){await run(async()=>{await api(`portal-access/invitations/${detail.value.portal.invitation.id}/${action}`,'POST',{});await show(detail.value.customer.id)})}
async function access(){await run(async()=>{await api('portal-access','PATCH',{id:detail.value.portal.access.id,active:!detail.value.portal.access.active});await show(detail.value.customer.id)})}
onMounted(load);onUnmounted(()=>clearTimeout(timer))
defineExpose({refresh:saved,show})
</script>
<template>
 <div v-if="error" class="error-box" role="alert">{{error}}</div>
 <section v-if="!detail" class="panel crm-panel">
  <header class="panel-heading"><h2>Clients</h2><button v-if="writable" class="primary" @click="edit('partners',null,{kind:'customer'})">+ Nouveau client</button></header>
  <div class="table-toolbar"><input v-model="query" aria-label="Rechercher des clients" type="search" placeholder="Nom, contact, téléphone, courriel…" @input="search"/><select v-model="archived" aria-label="État des clients" @change="page=1;load()"><option value="false">Actifs</option><option value="true">Archives</option><option value="all">Tous</option></select><select v-model="sort" aria-label="Trier les clients" @change="page=1;load()"><option value="name">Nom A–Z</option><option value="-name">Nom Z–A</option><option value="-created_at">Plus récents</option></select></div>
  <p v-if="loading" role="status">Chargement…</p><p v-else-if="!rows.length" class="empty-state">Aucun client.</p>
  <div class="crm-client-list"><article v-for="row in rows" :key="row.id"><button class="record-link" @click="show(row.id)">{{row.name}}</button><span>{{row.contact_name||'—'}}</span><span>{{row.email||'—'}}</span><span>{{row.phone||'—'}}</span><span>{{row.archived_at?'Archivé':'Actif'}}</span></article></div>
  <div class="table-pagination"><span>{{count}} clients</span><div><button class="secondary" :disabled="page===1" @click="page--;load()">Précédent</button><b>{{page}}</b><button class="secondary" :disabled="page*25>=count" @click="page++;load()">Suivant</button></div></div>
 </section>
 <section v-else class="panel crm-panel">
  <button class="text-btn" @click="detail=null;load()">← Tous les clients</button>
  <header class="panel-heading"><div><h2>{{detail.customer.name}}</h2><p>{{detail.customer.archived_at?'Client archivé':'Client actif'}}</p></div><button v-if="detail.writable" class="secondary" @click="edit('partners',detail.customer)">Modifier</button></header>
  <p>{{detail.customer.contact_name}} · {{detail.customer.phone}} · {{detail.customer.email}}</p><p>{{detail.customer.address}} {{detail.customer.city}} {{detail.customer.country}}</p>
  <div class="crm-metrics"><div v-for="key in ['orders','completed_missions','invoices','unpaid','billed','paid','balance','late']" v-show="detail.stats[key]!==undefined"><b>{{['balance','billed','paid'].includes(key)?money(detail.stats[key],org.currency):detail.stats[key]}}</b><span>{{({orders:'Commandes',completed_missions:'Missions terminées',invoices:'Factures',unpaid:'Impayées',billed:'Total facturé',paid:'Total payé',balance:'Solde à recevoir',late:'En retard'} as any)[key]}}</span></div></div>
  <div class="card-actions" v-if="!detail.customer.archived_at"><button v-if="detail.tabs.includes('quotes')&&catalog.find(x=>x.key==='invoices')?.writable" class="secondary" @click="create('invoices','quote')">Créer un devis</button><button v-if="detail.tabs.includes('orders')&&catalog.find(x=>x.key==='orders')?.writable" class="secondary" @click="create('orders')">Créer une commande</button><button v-if="detail.tabs.includes('invoices')&&catalog.find(x=>x.key==='invoices')?.writable" class="secondary" @click="create('invoices')">Créer une facture</button><button v-if="detail.tabs.includes('documents')&&catalog.find(x=>x.key==='documents')?.writable" class="secondary" @click="create('documents')">Ajouter un document</button><button v-if="detail.writable" class="secondary" @click="create('contacts')">Ajouter un contact</button></div>
  <div v-if="detail.portal" class="info-box"><template v-if="detail.portal.access">Portail {{detail.portal.access.active?'actif':'suspendu'}} <button class="secondary" @click="access">{{detail.portal.access.active?'Suspendre':'Réactiver'}}</button></template><template v-else-if="detail.portal.invitation">Invitation en attente <button class="secondary" @click="portalAction('resend')">Renvoyer</button><button class="secondary" @click="portalAction('cancel')">Annuler</button></template><button v-else-if="!detail.customer.archived_at" class="secondary" :disabled="!detail.customer.email" @click="invite">Inviter au portail</button></div>
  <button v-if="detail.can_contact" class="secondary" @click="discussion=!discussion">Contacter le client</button><ClientDiscussion v-if="discussion" :customer="detail.customer.id"/>
  <nav class="crm-tabs" aria-label="Dossier client"><button v-for="key in detail.tabs" class="secondary" :aria-current="tab===key?'page':undefined" @click="selectTab(key)">{{labels[key]}}</button></nav>
  <template v-if="tab==='overview'"><h3>Notes internes</h3><p>{{detail.customer.notes||'Aucune note.'}}</p><p>Dernière modification : {{new Date(detail.last_activity).toLocaleString('fr-FR')}}</p><button v-if="detail.writable" class="secondary" @click="archive">{{detail.customer.archived_at?'Restaurer le client':'Archiver le client'}}</button></template>
  <template v-else><p v-if="!history.length">Aucun enregistrement.</p><article v-for="row in history" :key="row.id" class="crm-history"><button v-if="tab!=='activity'" class="record-link" @click="edit(tab==='quotes'?'invoices':tab,row)">{{row.label||row.reference||row.name}}</button><b v-else>{{row.label||row.action}} {{row.reference}}</b><time v-if="tab==='activity'">{{new Date(row.created_at).toLocaleString('fr-FR')}}</time><span>{{states[row.kind==='quote'?row.quote_status:(row.payment_state||row.status)]||row.status}}</span><span v-if="row.overdue_days">En retard de {{row.overdue_days}} jour(s)</span><span v-if="tab==='documents'">{{row.shared_with_customer?'Partagé au portail':'Interne'}}</span><span v-if="row.total">Total : {{money(row.total,org.currency)}}</span><span v-if="tab==='invoices'">Payé : {{money(row.paid,org.currency)}} · Solde : {{money(row.balance,org.currency)}}</span><template v-if="tab==='quotes'&&catalog.find(x=>x.key==='invoices')?.writable"><button v-if="row.quote_status==='draft'" class="secondary" @click="commercial(row,'send')">Envoyer le devis</button><template v-if="row.quote_status==='sent'"><button class="secondary" @click="commercial(row,'resend')">Renvoyer le devis</button><button class="secondary" @click="commercial(row,'revoke-link')">Retirer le lien client</button><button class="secondary" @click="commercial(row,'accept')">Accepter</button><button class="secondary" @click="commercial(row,'refuse')">Refuser</button></template><button v-if="row.quote_status==='accepted'&&catalog.find(x=>x.key==='orders')?.writable" class="secondary" @click="commercial(row,'convert')">Créer la commande</button></template><template v-if="tab==='orders'&&catalog.find(x=>x.key==='orders')?.writable"><button v-if="row.status==='draft'" class="secondary" @click="act('orders',row,'confirm')">Confirmer la commande</button><button v-if="row.status==='confirmed'&&catalog.find(x=>x.key==='missions')?.writable" class="secondary" @click="plan(row)">Planifier la mission</button></template><template v-if="tab==='missions'&&catalog.find(x=>x.key==='missions')?.writable"><button v-if="row.status==='planned'" class="secondary" @click="act('missions',row,'start')">Démarrer</button><button v-if="row.status==='active'" class="secondary" @click="completing=row">Terminer</button></template><button v-if="tab==='missions'&&row.status==='completed'" class="secondary" @click="receipt=row">Justificatif signé</button><template v-if="tab==='invoices'&&catalog.find(x=>x.key==='invoices')?.writable"><button v-if="row.status==='draft'" class="secondary" @click="act('invoices',row,'issue')">Émettre la facture</button><button v-if="row.status==='issued'" class="secondary" @click="payment(row)">Enregistrer un paiement</button></template><button v-if="tab==='missions'&&row.status==='completed'&&catalog.find(x=>x.key==='invoices')?.writable" class="secondary" @click="commercial(row,'invoice')">Créer la facture</button></article><div class="table-pagination"><span>{{historyCount}} résultats</span><button class="secondary" :disabled="historyPage===1" @click="historyPage--;loadHistory()">Précédent</button><button class="secondary" :disabled="historyPage*25>=historyCount" @click="historyPage++;loadHistory()">Suivant</button></div></template>
 </section>
 <MissionCompletion v-if="completing" :mission="completing" @close="completing=null" @saved="completing=null;saved()"/>
 <DeliveryReceipt v-if="receipt" :mission="receipt" :canSign="['owner','admin','operations'].includes(org.role)" @close="receipt=null"/>
 <RecordEditor v-if="editor" :schema="editor" :record="record" :prefill="prefill" :currency="org.currency" :admin="['owner','admin'].includes(org.role)" @close="editor=null" @existing="(row:any)=>{editor=null;row.kind==='supplier'?edit('partners',row):show(row.id)}" @saved="saved"/>
</template>
<style scoped>
.crm-panel{padding:24px;min-width:0;overflow-wrap:anywhere}.crm-client-list article{display:grid;grid-template-columns:2fr 1fr 2fr 1fr auto;gap:16px;padding:18px 0;border-bottom:1px solid #e5eaf0;overflow-wrap:anywhere}.crm-metrics{display:flex;gap:16px;flex-wrap:wrap;margin:24px 0}.crm-metrics div{display:grid;gap:8px;flex:1;min-width:120px;padding:16px;background:#f5f8fb;border-radius:12px}.crm-metrics b{font-size:24px}.crm-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}.crm-tabs [aria-current]{background:#e8f2ff}.crm-history{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:18px 0;border-bottom:1px solid #e5eaf0}.crm-panel .card-actions{display:flex;gap:8px;flex-wrap:wrap}.crm-panel button{min-height:44px}.crm-panel .table-toolbar{flex-wrap:wrap}.crm-panel input{max-width:100%;min-width:0}@media(max-width:600px){.crm-panel{padding:16px}.crm-client-list article{grid-template-columns:1fr;gap:8px;padding:16px;border:1px solid #e5eaf0;border-radius:12px;margin:12px 0}.crm-panel .table-pagination{flex-wrap:wrap;gap:12px}.crm-panel .panel-heading{flex-wrap:wrap;gap:12px}}
</style>
